#!/usr/bin/env python3"""Worked example ΓÇö exercises every dtdeck component. Copy and adapt.    python3 example_deck.py                     # -> /tmp/example_raw.pptx    python3 brand.py /tmp/example_raw.pptx --out ~/Desktop/Example.pptx \        --footer "Acme Corp  ┬╖  Solution Overview""""import osimport syssys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))from dtdeck import *  # noqa: F403OUT = '/tmp/example_raw.pptx'prs = new_deck()# ---------------------------------------------------------------- 1. covers = new_slide(prs)_, t = tb(s, L, Inches(0.55), Inches(11.0), Inches(0.3))run(t.paragraphs[0], 'SOLUTION OVERVIEW  ┬╖  PLATFORM MODERNIZATION', 11, LBL, F_MONO, spc=240)_, t = tb(s, L, Inches(1.30), Inches(11.4), Inches(1.7))p = t.paragraphs[0]p.line_spacing = 1.02run(p, 'One control plane,', 44, TXT, F_MED, bold=True)p2 = t.add_paragraph()p2.line_spacing = 1.02run(p2, 'every signal accounted for.', 44, LBL, F_MED, bold=True)_, t = tb(s, L, Inches(3.30), Inches(10.4), Inches(1.0))p = t.paragraphs[0]p.line_spacing = 1.45run(p, 'A short positioning paragraph naming the customer, the shape of the '       'solution and the single outcome that matters. Three lines is plenty ΓÇö '       'the tiles below carry the numbers.', 13, TXT2, F_LT)tiles(s, [    ('Ingest requirement', '125 TB/day', 'Scaling to 300 TB/day.', LIME),    ('Estate', '5 DCs', '~27,000 servers.', BLUE),    ('Destinations', '3', 'One collection, no duplication.', PURP),    ('Data ownership', 'Customer', 'Partner owns no data.', CYAN),], top=5.60)# ---------------------------------------------------------------- 2. stacked panelss = new_slide(prs)eyebrow(s, '01', 'The mandate')headline(s, 'What the requirements actually ask for')deck(s, 'Two or three sentences of context. This is where the tension between '        'requirements gets named, so the panels below can stay terse and factual.')y = block(s, Inches(1.92), 'Ingest everything', 'SCALE', BLUE, [    'A plain bullet stating one fact, kept to a single line where possible.',    'Agent and agentless collection across every operating system in scope.',    ('A bold lead-in. ', 'Then the normal continuation of the sentence.'),])y = block(s, y + Inches(0.16), 'Protect and segregate', 'COMPLIANCE', LIME, [    'Sensitive data protected before it leaves the customer environment.',    'Role-based access control and multi-tenancy across teams.',    ('An explicit contractual term, ', 'quoted from the requirement document.'),])y = block(s, y + Inches(0.16), 'Retain and analyze', 'OPERATE', PURP, [    'Tiered storage with configurable retention windows.',    'Correlation across logs and metrics; anomaly and threshold alerting.',])footnote(s, 'Reading the requirements together:',         'name the tension the three clusters create, and the single design '         'decision that resolves it.', top=6.52)# ---------------------------------------------------------------- 3. tables = new_slide(prs)eyebrow(s, '02', 'Coverage')headline(s, 'Mapped against the requirements, line by line')deck(s, 'Coverage stated as design intent. Use status pills so a reviewer can '        'scan the middle column and stop where it is not green.', top=1.22)table(s, ['Requirement', 'Coverage', 'How it is delivered'], [3.75, 1.40, 6.56], [    ['Ingest at volume, no loss', ('Addressed', LIME),     'Persistent-queue architecture scaled horizontally per collector.'],    ['Federated search across sites', ('Addressed', LIME),     'One control plane per site; a single federated query across the subset.'],    ['All OS flavors, agent + agentless', ('Addressed', LIME),     'Native collectors for every listed OS, plus agentless receivers.'],    ['Open standards', ('Addressed', LIME),     'OpenTelemetry-native end to end ΓÇö open protocols for config and transport.'],    ['Volume reduction at scale', ('Later phase', '6F84AE'),     'Mechanism is filtering plus conversion to metrics; ratio set against real data.'],], top=1.90, rowh=0.50)# ---------------------------------------------------------------- 4. two columnss = new_slide(prs)eyebrow(s, '03', 'Once the data lands')headline(s, 'From a raw signal to a business outcome')deck(s, 'Four parallel themes as a two-by-two. Build both columns, then start the '        'next row from max() of the two bottom edges so the rows stay aligned.')CW, RX = Inches(5.72), Inches(7.07)r1 = Inches(1.95)a = block(s, r1, 'Infrastructure', 'DOMAIN', BLUE, [    'Host, process and OS-level health across the estate in one view.',    'Capacity trends with anomaly detection on resource and error signals.',], width=CW)b = block(s, r1, 'Network', 'DOMAIN', CYAN, [    'Device syslog correlated with connectivity and latency issues.',    'Security events still reach the existing SIEM in parallel.',], left=RX, width=CW)r2 = max(a, b) + Inches(0.18)block(s, r2, 'Application', 'DOMAIN', PURP, [    'Logs linked to traces, metrics and topology automatically.',    'Causal root cause: one answer, not a wall of alerts.',], width=CW)block(s, r2, 'Business', 'DOMAIN', LIME, [    'Transaction-bearing lines converted to business events.',    'Forecasts flag degradation before it breaches an SLA.',], left=RX, width=CW)tiles(s, [    ('Domains served', '4', 'Infra, network, app, business.', BLUE),    ('Correlation', 'Automatic', 'Logs to traces and topology.', PURP),    ('Root cause', 'Causal AI', 'One answer, not an alert storm.', LIME),    ('Ticketing', 'Agentic', 'Opened and updated automatically.', CYAN),], top=5.88)prs.save(OUT)print('wrote %s (%d slides)' % (OUT, len(prs.slides._sldIdLst)))print('now run:  python3 brand.py %s --out ~/Desktop/Example.pptx '      '--footer "Acme Corp  ┬╖  Solution Overview"' % OUT)